import{_ as a,o as t,c as r,a2 as d}from"./chunks/framework.DgVVaeR-.js";const P=JSON.parse('{"title":"プライバシーポリシー","description":"","frontmatter":{"title":"プライバシーポリシー"},"headers":[],"relativePath":"privacy-policy.md","filePath":"privacy-policy.md","lastUpdated":1791013521000}'),i={name:"privacy-policy.md"};function o(l,e,c,n,h,p){return t(),r("div",null,[...e[0]||(e[0]=[d('<h1 id="プライバシーポリシー" tabindex="-1">プライバシーポリシー <a class="header-anchor" href="#プライバシーポリシー" aria-label="Permalink to &quot;プライバシーポリシー&quot;">​</a></h1><p>最終更新日: 2026年10月3日</p><p>PalleriaはPixivの非公式クライアントです。このページは、現行ソースで確認できるデータの保存・通信と、利用者が変更できる設定を説明します。</p><h2 id="端末内に保存するデータ" tabindex="-1">端末内に保存するデータ <a class="header-anchor" href="#端末内に保存するデータ" aria-label="Permalink to &quot;端末内に保存するデータ&quot;">​</a></h2><table tabindex="0"><thead><tr><th>データ</th><th>保存方法</th></tr></thead><tbody><tr><td>Pixiv認証トークンなどの秘密値</td><td>通常はAndroid Keystoreをマスター鍵に利用したEncryptedSharedPreferences。移行・ストア復旧時は既存値を保持して再試行する処理があります</td></tr><tr><td>アカウント表示情報、検索・閲覧履歴、お気に入りタグ、保存作品の情報</td><td>Room DB。アプリ独自にDB全体を暗号化する設定はありません</td></tr><tr><td>一般設定</td><td>Preferences DataStore等</td></tr><tr><td>取得した画像</td><td>画像キャッシュ、保存用ディレクトリ、利用者が選んだ保存先。画像ファイル全体を独自に暗号化するものではありません</td></tr><tr><td>PallaSyncの鍵・同期状態</td><td>鍵はEncryptedSharedPreferences、送受信キュー等はRoom</td></tr></tbody></table><p>履歴の記録や削除、保存先、キャッシュ等は対応する設定画面で管理できます。JSONバックアップを書き出した場合は、そのファイルも利用者が管理する必要があります。</p><h2 id="外部との通信" tabindex="-1">外部との通信 <a class="header-anchor" href="#外部との通信" aria-label="Permalink to &quot;外部との通信&quot;">​</a></h2><p>Pixivの認証・作品取得・検索・ブックマークなどを利用すると、各操作に必要な情報をPixivへ送信します。画像プロキシ等を設定した場合は、その接続先も通信経路に含まれます。更新確認ではGitHubのリリース情報を取得します。</p><p>Discord連携、PallaSync、テレメトリなどを有効にした場合は、それぞれの機能に必要な通信が追加されます。</p><h2 id="テレメトリとクラッシュレポート" tabindex="-1">テレメトリとクラッシュレポート <a class="header-anchor" href="#テレメトリとクラッシュレポート" aria-label="Permalink to &quot;テレメトリとクラッシュレポート&quot;">​</a></h2><p><code>sendTelemetry</code> の既定値は <code>false</code> です。設定で有効にした場合だけGlitchTip互換のSentry Android SDKを初期化し、無効にすると停止します。送信先は <code>glitchtip.yunfi.f5.si</code> です。</p><p>有効時には例外・スタックトレース、端末・OS情報、パフォーマンス情報などを送信します。トレースの設定サンプリング率は1.0です。既定のPII送信は無効ですが、呼び出し元が付ける追加情報には<strong>検索語、URL、作品IDなどが含まれる経路があります</strong>。検索内容が一切含まれないとは保証できません。送信を望まない場合はテレメトリを無効のまま利用してください。</p><p>詳細は<a href="/Palleria/dev/telemetry-spec">テレメトリ仕様</a>と <code>GlitchTipTelemetry.kt</code>、各 <code>recordException</code> 呼び出しを参照してください。</p><h2 id="pallasync" tabindex="-1">PallaSync <a class="header-anchor" href="#pallasync" aria-label="Permalink to &quot;PallaSync&quot;">​</a></h2><p>チェーンに参加して同期を有効にすると、お気に入りタグ、検索履歴、ミュート、既読フィード作品、閲覧履歴を同期対象にします。認証トークンや保存画像ファイルを丸ごと同期するものではありません。</p><p>通信レコードの本文は2.1形式ではXChaCha20-Poly1305で暗号化し、旧2.0形式も読み取ります。端末内の鍵保存に使うAES系の暗号と、通信本文の暗号は別です。サーバーは配送に必要なチェーンIDなどのメタデータを扱います。同期コード・鍵素材を持つ端末はチェーンへ参加できるため、これらを第三者へ公開しないでください。</p><h2 id="画面保護" tabindex="-1">画面保護 <a class="header-anchor" href="#画面保護" aria-label="Permalink to &quot;画面保護&quot;">​</a></h2><p>PIN・生体認証によるアプリロック、電卓表示、セキュアウィンドウ、タスク切り替え画面の秘匿設定があります。画面保護の動作はOS・端末環境にも依存します。これらは保存済み画像やDB全体を暗号化する機能ではありません。</p><h2 id="更新と問い合わせ" tabindex="-1">更新と問い合わせ <a class="header-anchor" href="#更新と問い合わせ" aria-label="Permalink to &quot;更新と問い合わせ&quot;">​</a></h2><p>実装や取り扱いが変わった場合は、このページを更新します。問い合わせは<a href="https://github.com/yunfie-twitter/Palleria/issues" target="_blank" rel="noreferrer">GitHub Issues</a>へお願いします。認証トークン・パスワード・同期コードは投稿しないでください。</p>',20)])])}const u=a(i,[["render",o]]);export{P as __pageData,u as default};
